{
  "correction_rules": [
    "Reduce forecast overshoots following sharp price spikes, especially when sentiment is neutral or negative.",
    "Adjust forecasts downward if sentiment turns negative (e.g., sentiment < 0.00) and price is trending upward.",
    "Apply mean reversion bias: if forecast is significantly above recent 5-day average, reduce by 5-10% for next period.",
    "Increase downward bias when sentiment is positive (e.g., sentiment > 0.50) and price is trending downward.",
    "Lag correction: if true outcome is significantly lower than forecast, reduce next period’s forecast by 10-15% to account for delayed market reaction.",
    "Avoid over-optimism in early forecast periods; use sentiment history to dampen initial forecast peaks."
  ]
}
